const esc = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
const para = t => t.startsWith("> ")
  ? `<blockquote>${esc(t.slice(2))}</blockquote>`
  : `<p>${esc(t)}</p>`;

const list = document.getElementById("blog-list");
let year = "";
list.innerHTML = POSTS.map(p => {
  const y = p.date.slice(-4);
  const head = y !== year ? `<h2 class="blog-year">${year = y}</h2>` : "";
  return head + (p.body
    ? `<article class="extra post"><div class="extra-head"><h3 class="extra-title">${esc(p.title)}</h3><span class="extra-date">${esc(p.date)}</span></div><div class="post-body">${p.body.map(para).join("")}</div></article>`
    : `<div class="post-slim"><span class="extra-date">${esc(p.date)}</span><span class="post-slim-title">${esc(p.title)}</span></div>`);
}).join("");
document.getElementById("blog-count").textContent = `${POSTS.length} posts`;

document.getElementById("forum-list").innerHTML = THREADS.map(([topic, msgs]) => `
  <article class="extra thread"><div class="extra-head"><span class="extra-type">FORUM</span><h3 class="extra-title">${esc(topic)}</h3></div>
  ${msgs.map(([who, when, text]) => `<div class="msg"><div class="msg-who"><strong>${esc(who)}</strong> <span class="extra-date">${esc(when)}</span></div><p>${esc(text)}</p></div>`).join("")}
  </article>`).join("");
